// event funtions
/**
 * Handle the supplied LVGL event by loading the main screen with a 100 ms fade on a long
 * press; ignore other event codes.
 *
 * Input: e is an LVGL event. Returns nothing; uses lazy main-screen construction and
 * preserves debug during a 100 ms transition. Non-long-press events do not change screen
 * selection.
 */
void ui_event_DebugScreen(lv_event_t *e) {
  lv_event_code_t event_code = lv_event_get_code(e);

  if (event_code == LV_EVENT_LONG_PRESSED) {
    _ui_screen_change(&ui_MainScreen, LV_SCR_LOAD_ANIM_FADE_ON, 100, 0, &ui_MainScreen_screen_init);
  }
}

